// Pinia store
import { defineStore } from 'pinia';
import { ref, computed } from 'vue';

export const useCartStore = defineStore('cart', () => {
  // State
  const items = ref<CartItem[]>([]);
  const promoCode = ref<string | null>(null);

  // Getters
  const itemCount = computed(() => items.value.reduce((sum, i) => sum + i.quantity, 0));
  const total = computed(() => {
    let t = items.value.reduce((sum, i) => sum + i.price * i.quantity, 0);
    return promoCode.value === 'SAVE10' ? t * 0.9 : t;
  });

  // Actions
  function addItem(product: Product) {
    const existing = items.value.find(i => i.id === product.id);
    if (existing) {
      existing.quantity++;
    } else {
      items.value.push({ ...product, quantity: 1 });
    }
  }

  function removeItem(id: number) {
    items.value = items.value.filter(i => i.id !== id);
  }

  function applyPromo(code: string) {
    promoCode.value = code;
  }

  return { items, promoCode, itemCount, total, addItem, removeItem, applyPromo };
});

